import{_ as e,c,o as d,b0 as a}from"./chunks/framework.BWMBvyU7.js";const t="/programming-docs/assets/image-20220525135326426.9g8X7lwO.png",n="/programming-docs/assets/image-20220525145319809.BtiAl8IH.png",s="/programming-docs/assets/1.CN0ZFpNf.gif",r="/programming-docs/assets/image-20220525153117719.J3COe-Sy.png",h=JSON.parse('{"title":"LV005-线程同步简介","description":null,"frontmatter":{"title":"LV005-线程同步简介","date":"2026-03-16T21:40:42.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/os/thread-synchronization/126d38f3731a2acf8ff256aa","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-16T21:40:42.684Z","fulluuid":"f8ff256aa72b4a86a4894176d8fd35c8","useduuid":"f8ff256aa"}},"headers":[],"relativePath":"sdoc/os/thread-synchronization/126d38f3731a2acf8ff256aa.md","filePath":"sdoc/03-操作系统/07-线程同步/LV005-线程同步简介.md","lastUpdated":1773672539000}'),i={name:"sdoc/os/thread-synchronization/126d38f3731a2acf8ff256aa.md"};function l(m,o,p,u,g,f){return d(),c("div",null,[...o[0]||(o[0]=[a('<h1 id="lv005-线程同步简介" tabindex="-1">LV005-线程同步简介 <a class="header-anchor" href="#lv005-线程同步简介" aria-label="Permalink to &quot;LV005-线程同步简介&quot;">​</a></h1><p>本文主要是线程同步——线程同步基础知识的相关笔记，若笔记中有错误或者不合适的地方，欢迎批评指正😃。</p><h2 id="一、竞争条件" tabindex="-1">一、竞争条件 <a class="header-anchor" href="#一、竞争条件" aria-label="Permalink to &quot;一、竞争条件&quot;">​</a></h2><p>前边我们学习并行和并发的时候知道，在单核 <code>CPU</code> 系统里，为了实现多个程序同时运行的假象，操作系统通常以时间片调度的方式，让每个进程执行每次执行一个时间片，时间片用完了，就切换下一个进程运行，由于这个时间片的时间很短，于是就造成了同时运行的假象。</p><p>另外，操作系统也为每个进程创建巨大、私有的虚拟内存的假象，这种地址空间的抽象让每个程序好像拥有自己的内存，而实际上操作系统在背后秘密地让多个地址空间复用物理内存或者磁盘。</p><p>如果一个程序只有一个执行流程，也代表它是单线程的。当然一个程序可以有多个执行流程，也就是所谓的多线程程序，线程是调度的基本单位，进程则是资源分配的基本单位。所以，线程之间是可以共享进程的资源，比如代码段、堆空间、数据段、打开的文件等资源，但每个线程都有自己独立的栈空间。</p><img src="'+t+'" alt="image-20220525135326426" style="zoom:33%;"><p>那么问题就出现了，多个线程是有共享资源的，那若是这个线程还没有访问完毕，另一个线程也要访问，要是都是读取那感觉还好，那要是一个写一个读怎么办，这样得到的数据不就有问题了吗？我们可以看一下这个例子：</p><p>现在有两个线程，线程<code>1</code>和线程<code>2</code>，还有一个全局变量<code>num</code>，当前<code>num</code>的值是<code>5</code>，现在两个线程都是对<code>num</code>进行<code>+1</code>操作，我们下边分析一种可能会出现的情况：</p><p>将<code>num</code>加<code>1</code>在汇编中其实需要三步：</p><img src="'+n+'" alt="image-20220525145319809" style="zoom:40%;"><p>假设我们的线程<code>1</code>进入这个代码区域，它将<code>num</code> 的值（此时是 <code>5</code> ）从内存加载到它的寄存器中，然后它向寄存器加<code>1</code>，此时在寄存器中的<code>num</code> 值是 <code>6</code>。</p><p>但是这个时候，<strong>时钟中断发生</strong>，操作系统将当前正在运行的线程的状态保存到线程的线程控制块 <code>TCB</code>。而此时线程 <code>2</code> 被调度运行，并进入同一段代码。它也执行了第一条指令，从内存获取<code>num</code> 值并将其放入到寄存器中，此时内存中 <code>num</code> 的值仍为 <code>5</code>（线程<code>1</code>还未来得及将<code>6</code>放回内存），因此线程 <code>2</code> 寄存器中的 <code>num</code> 值也是 <code>5</code>。假设线程 <code>2</code> 执行接下来的两条指令，将寄存器中的 <code>num</code> 值 <code>+ 1</code>，然后将寄存器中的<code>num</code> 值保存到内存中，于是此时全局变量 <code>num</code> 值是<code>6</code>。</p><p>最后，又发生一次上下文切换，线程 <code>1</code> 恢复执行。还记得它已经执行了两条汇编指令，现在准备执行最后一条指令。线程 <code>1</code> 寄存器中的 <code>num</code> 值是<code>6</code>，因此，执行最后一条指令后，将值保存到内存，全局变量 <code>num</code> 的值再次被设置为 <code>6</code>。</p><p>两个线程都运行了，都是将<code>num</code>加<code>1</code>，理论上说，最终的<code>num</code>应该为<code>7</code>才对，但是由于<strong>不可控的调度</strong>，导致最后 <code>num</code>值却是 <code>6</code>。</p><img src="'+s+'" alt="1" style="zoom:60%;"><p>这样的情况就叫做竞争条件（<code>race condition</code>），当多线程相互竞争操作共享变量时，在执行过程中发生了上下文切换，我们得到了错误的结果，事实上，每次运行都可能得到不同的结果，因此输出的结果存在不确定性（<code>indeterminate</code>）。</p><h2 id="二、互斥" tabindex="-1">二、互斥 <a class="header-anchor" href="#二、互斥" aria-label="Permalink to &quot;二、互斥&quot;">​</a></h2><p>还是以上边的例子，由于多线程执行操作共享变量的这段代码可能会导致竞争状态，因此我们将此段代码称为<strong>临界区</strong>（<code>critical section</code>），它是访问共享资源的代码片段，一定不能让多个线程同时执行。</p><p>我们希望这段代码是<strong>互斥</strong>（<code>mutualexclusion</code>）的，也就说保证一个线程在临界区执行时，其他线程应该被阻止进入临界区，也就是这段代码执行过程中，最多只能出现一个线程。</p><img src="'+r+'" alt="image-20220525153117719" style="zoom:45%;"><h2 id="三、同步" tabindex="-1">三、同步 <a class="header-anchor" href="#三、同步" aria-label="Permalink to &quot;三、同步&quot;">​</a></h2><p>互斥解决了多线程对临界区的使用问题。这种基于临界区控制的交互作用是比较简单的，只要一个线程进入了临界区，其他试图想进入临界区的线程都会被阻塞着，直到第一个线程离开了临界区。</p><p>我们都知道在多线程里，每个线程并不一定是顺序执行的，它们基本是以各自独立的、不可预知的速度向前推进，但有时候我们又希望多个线程能密切合作，以实现一个共同的任务。</p><p>例如，线程 <code>1</code> 是负责读入数据的，而线程 <code>2 </code>是负责处理数据的，这两个线程是相互合作、相互依赖的。线程 <code>2</code> 在没有收到线程 <code>1</code> 的唤醒通知时，就会一直阻塞等待，当线程 <code>1</code> 读完数据需要把数据传给线程 <code>2</code> 时，线程 <code>1</code> 会唤醒线程 <code>2</code>，并把数据交给线程 <code>2</code> 处理。</p><p>所谓同步，就是并发线程在一些关键点上可能需要互相等待与互通消息，这种相互制约的等待与互通信息称为<strong>线程同步</strong>。</p>',26)])])}const b=e(i,[["render",l]]);export{h as __pageData,b as default};
